package cn.hydrogen.launcher;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.io.*;import java.util.*;
/** Exercises the real bootstrap with first-map host state reset, preserving native permissions/consents. */
final class FirstMapSetupFlow {
 final Instrumentation test;final boolean explicitOff;MainActivity desktop;UnifiedBootstrapActivity bootstrap;Object setup;int passed;StringBuilder report=new StringBuilder();
 interface Probe{boolean ready()throws Exception;}
 FirstMapSetupFlow(Instrumentation t,boolean off){test=t;explicitOff=off;}
 Object field(Object target,String name)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}
 Object staticField(Class<?> target,String name)throws Exception{Field f=target.getDeclaredField(name);f.setAccessible(true);return f.get(null);}
 void main(Runnable action){Throwable[] failure={null};test.runOnMainSync(()->{try{action.run();}catch(Throwable e){failure[0]=e;}});if(failure[0]!=null)throw new AssertionError(failure[0]);}
 void await(String why,int millis,Probe probe)throws Exception{long until=SystemClock.elapsedRealtime()+millis;while(SystemClock.elapsedRealtime()<until){boolean[] ready={false};Throwable[] failure={null};main(()->{try{ready[0]=probe.ready();}catch(Throwable e){failure[0]=e;}});if(failure[0]!=null)throw new AssertionError(failure[0]);if(ready[0])return;Thread.sleep(100);}throw new AssertionError("Timeout "+why+"; startup="+UnifiedInitService.status());}
 void require(boolean value,String why){if(!value)throw new AssertionError(why);passed++;report.append("PASS ").append(why).append('\n');}
 static final class SavedPrefs {final SharedPreferences pref;final Map<String,?> saved;SavedPrefs(SharedPreferences p){pref=p;saved=new HashMap<>(p.getAll());}@SuppressWarnings("unchecked") void restore(){SharedPreferences.Editor e=pref.edit().clear();for(Map.Entry<String,?> item:saved.entrySet()){String k=item.getKey();Object v=item.getValue();if(v instanceof String)e.putString(k,(String)v);else if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof Long)e.putLong(k,(Long)v);else if(v instanceof Float)e.putFloat(k,(Float)v);else if(v instanceof Set)e.putStringSet(k,(Set<String>)v);else throw new AssertionError("Unknown pref type");}if(!e.commit())throw new AssertionError("Cannot restore prefs");}}
 View desc(View root,String name){if(name.contentEquals(root.getContentDescription()==null?"":root.getContentDescription()))return root;if(root instanceof ViewGroup)for(int n=0;n<((ViewGroup)root).getChildCount();n++){View v=desc(((ViewGroup)root).getChildAt(n),name);if(v!=null)return v;}return null;}
 void tap(View v)throws Exception{int[] xy=new int[2];main(()->v.getLocationOnScreen(xy));long now=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,xy[0]+v.getWidth()/2f,xy[1]+v.getHeight()/2f,0),up=MotionEvent.obtain(now,now+90,MotionEvent.ACTION_UP,xy[0]+v.getWidth()/2f,xy[1]+v.getHeight()/2f,0);try{test.sendPointerSync(down);test.sendPointerSync(up);}finally{down.recycle();up.recycle();}}
 void screenshot(String name)throws Exception{if(Build.VERSION.SDK_INT>=18){android.graphics.Bitmap image=test.getUiAutomation().takeScreenshot();if(image!=null)try(OutputStream out=new FileOutputStream(new File(test.getTargetContext().getExternalFilesDir(null),name))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);image.recycle();}}}
 void run(){Context ctx=test.getTargetContext();Config cfg=new Config(ctx);TestPreferences desktopSaved=new TestPreferences(ctx);SavedPrefs init=new SavedPrefs(ctx.getSharedPreferences("unified-native-initialization",0)),startup=new SavedPrefs(ctx.getSharedPreferences("unified-startup-session",0)),ui=new SavedPrefs(ctx.getSharedPreferences("cn.hydrogen.launcher.UnifiedBootstrapActivity",0));boolean ok=false;Bundle result=new Bundle();report.append("Real first-map setup; map preference=").append(explicitOff?"explicit false":"absent").append("; existing native permissions/consents retained\n");try{
  require(!UnifiedInitService.active(),"no competing initialization owner");
  main(()->{cfg.p.edit().putBoolean("autoRecoverApps",true).remove("amapFloating").commit();if(explicitOff)cfg.p.edit().putBoolean("amapFloating",false).commit();init.pref.edit().remove(Config.MAP).commit();startup.pref.edit().putBoolean("active",false).commit();ui.pref.edit().putBoolean("firstSetupExplained",true).putBoolean("permissionPrompted",true).putBoolean("overlayPrompted",true).commit();});
  bootstrap=(UnifiedBootstrapActivity)test.startActivitySync(new Intent(ctx,UnifiedBootstrapActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));
  await("native first setup dialog",60000,()->{java.lang.ref.WeakReference<?> current=(java.lang.ref.WeakReference<?>)staticField(UnifiedBootstrapActivity.class,"current");if(current!=null&&current.get() instanceof UnifiedBootstrapActivity)bootstrap=(UnifiedBootstrapActivity)current.get();setup=field(bootstrap,"mapSetup");return setup!=null&&((Dialog)field(setup,"dialog")).isShowing();});
  require(UnifiedInitService.firstMapPending()&&!UnifiedInitService.admitted(),"first-use dialog does not bypass desktop admission");
  require(cfg.p.contains("amapFloating")==explicitOff&&(!explicitOff||!cfg.b("amapFloating",true)),"opening setup preserves the original map preference");
  AmapFloatingController controller=(AmapFloatingController)field(setup,"map");Button next=(Button)field(setup,"next");
  try{await("real setup map connected and continue enabled",18000,()->controller.connected()&&next.isEnabled());}catch(Throwable error){report.append("setup hint=").append(((TextView)field(setup,"hint")).getText()).append(" requested=").append(field(controller,"requested")).append(" visible=").append(controller.windowVisible()).append('\n');screenshot("startup35-first-map-blocked.png");throw error;}
  require(controller.connected()&&controller.windowVisible(),"native map really renders in first-use window with the user preference preserved");
  require(!UnifiedInitService.admitted()&&!init.pref.getBoolean(Config.MAP,false),"ready map still waits for user confirmation");screenshot("startup35-first-map-"+(explicitOff?"off":"absent")+".png");tap(next);
  await("both real interfaces and focused desktop",60000,()->{Object ref=field(MapWorkspace.get(ctx),"main");desktop=ref==null?null:(MainActivity)((java.lang.ref.WeakReference<?>)ref).get();return UnifiedInitService.admitted()&&desktop!=null&&!desktop.isFinishing()&&desktop.hasWindowFocus();});
  require(init.pref.getBoolean(Config.MAP,false)&&init.pref.getBoolean(Config.MUSIC,false),"first-use completion persists only after actual dual-interface admission");
  require((Boolean)field(controller,"released"),"first-use map controller is released after continuing");
  require(cfg.p.contains("amapFloating")==explicitOff&&(!explicitOff||!cfg.b("amapFloating",true)),"successful setup leaves normal map preference unchanged");
  main(()->desktop.showPage(MainActivity.CARDS));Thread.sleep(500);
  if(explicitOff)require(!((AmapFloatingController)field(desktop,"floatingMap")).windowVisible(),"explicitly disabled desktop card remains hidden after setup");
  else{await("normal desktop card defaults on",15000,()->desktop.mapCardConnected());require(((AmapFloatingController)field(desktop,"floatingMap")).windowVisible(),"normal desktop card defaults on after setup");tap(desc(desktop.getWindow().getDecorView(),"切换高德悬浮地图"));await("disable default-on desktop card",5000,()->!((AmapFloatingController)field(desktop,"floatingMap")).windowVisible());}
  View toggle=desc(desktop.getWindow().getDecorView(),"切换高德悬浮地图");tap(toggle);await("explicit user enable after first setup",15000,()->desktop.mapCardConnected());require(cfg.b("amapFloating",false),"user can explicitly enable real map after setup");tap(desc(desktop.getWindow().getDecorView(),"切换高德悬浮地图"));await("disable native map",5000,()->!((AmapFloatingController)field(desktop,"floatingMap")).windowVisible());require(!cfg.b("amapFloating",true),"user can disable map again");ok=true;
 }catch(Throwable e){report.append("FAIL ").append(e).append('\n');}finally{try{main(()->{UnifiedInitService.recoveryRequested();if(setup!=null)((UnifiedMapSetup)setup).close();if(desktop!=null&&!desktop.isFinishing())desktop.finish();if(bootstrap!=null&&!bootstrap.isFinishing())bootstrap.finish();});Thread.sleep(400);desktopSaved.close();init.restore();startup.restore();ui.restore();}catch(Throwable e){ok=false;report.append("RESTORE FAIL ").append(e).append('\n');}}
 report.append("RESULT first-map checks=").append(passed).append(ok?" PASS":" FAIL").append('\n');result.putString("stream",report.toString());test.finish(ok?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);
 }
}
